import sys
from xml.dom import minidom

PATH = 'unpacked/word/document.xml'
doc = minidom.parse(PATH)
W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'


def para_text(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        if t.firstChild:
            parts.append(t.firstChild.nodeValue)
    return ''.join(parts)


def add_underline(rpr):
    for u in [n for n in rpr.childNodes
              if n.nodeType == n.ELEMENT_NODE and n.tagName == 'w:u']:
        rpr.removeChild(u)
    u = doc.createElementNS(W, 'w:u')
    u.setAttribute('w:val', 'single')
    rpr.appendChild(u)


headlines = []
for p in doc.getElementsByTagName('w:p'):
    text = para_text(p)
    if text and any(c.isalpha() for c in text) and text == text.upper():
        for r in p.getElementsByTagName('w:r'):
            rprs = r.getElementsByTagName('w:rPr')
            if rprs:
                add_underline(rprs[0])
            else:
                rpr = doc.createElementNS(W, 'w:rPr')
                r.insertBefore(rpr, r.firstChild)
                add_underline(rpr)
        headlines.append(text)

# Serialize: toxml() -> str, then encode as ascii with xml char references
out = doc.toxml()
if out.startswith('<?xml version="1.0" ?>'):
    out = out.replace('<?xml version="1.0" ?>',
                      '<?xml version="1.0" encoding="ascii"?>', 1)
data = out.encode('ascii', 'xmlcharrefreplace')
with open(PATH, 'wb') as f:
    f.write(data)

print('UNDERLINED:', len(headlines))
for h in headlines:
    print(' -', h)

from xml.dom import minidom

doc = minidom.parse('unpacked/word/document.xml')


def para_text(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        if t.firstChild:
            parts.append(t.firstChild.nodeValue)
    return ''.join(parts)


problems = []
underlined = []
not_underlined = []
for p in doc.getElementsByTagName('w:p'):
    text = para_text(p)
    if not text:
        continue
    runs = p.getElementsByTagName('w:r')
    has_u = any(r.getElementsByTagName('w:u') for r in runs)
    is_headline = any(c.isalpha() for c in text) and text == text.upper()
    if is_headline and not has_u:
        problems.append(f'MISSING underline: {text!r}')
    if not is_headline and has_u:
        problems.append(f'UNEXPECTED underline: {text!r}')
    (underlined if has_u else not_underlined).append(text)

print('HEADLINES UNDERLINED:')
for t in underlined:
    print('  -', t)
print('NON-HEADLINES WITH NO UNDERLINE:', len(not_underlined))
print('PROBLEMS:', problems if problems else 'none')

# Ensure the u element is schema-ordered (after sz-cs) and single-valued
for p in doc.getElementsByTagName('w:p'):
    for r in p.getElementsByTagName('w:r'):
        for u in r.getElementsByTagName('w:u'):
            assert u.getAttribute('w:val') == 'single', u.toxml()
            rpr = u.parentNode
            idx = [n for n in rpr.childNodes if n.nodeType == n.ELEMENT_NODE]
            assert idx[-1] == u, f'w:u not last in rPr: {rpr.toxml()}'
print('ORDER/VALUE CHECK: ok')

